function operation(id,actor,call){
 const c=cfg(id),a=c&&own(c.actions,call?.id)?c.actions[call.id]:null;if(!a||!a.owners.includes(actor))return null;
 const args=call.args||{},p=a.parameters;if(Object.keys(args).some(k=>!own(p,k))||Object.entries(p).some(([k,vs])=>!vs.includes(args[k])))return null;
 return a;
}
